// Game data from src/data (generated by scripts/build-data.ts from design/data): Fate cards, counter types, objective
// chits, smoke markers, maps, scenarios and the RSG tables. The JSON keeps hex labels ("F6"); everything here hands out
// HexIds. Nothing in this module is mutated after loading.
import cardsJson from '../data/cards.json';
import countersJson from '../data/counters.json';
import { parseHex } from './hex';
import type { CardId, ChitId, CounterType, FateCard, HexSide, Nation, Quality } from './types';

// ---------------------------------------------------------------------------------------------------------------------
// Fate cards

/** All 216 Fate cards by id ("G-01", "A-01", "R-01"). */
export const CARDS: Readonly<Record<CardId, FateCard>> = Object.freeze(
  Object.fromEntries(
    cardsJson.cards.map((c): [CardId, FateCard] => [
      c.id,
      Object.freeze({
        ...(c as Omit<FateCard, 'hex' | 'breeze'>),
        hex: parseHex(c.hex),
        breeze: (c.breeze ?? null) as HexSide | null,
      }),
    ]),
  ),
);

const DECKS: Record<Nation, CardId[]> = { German: [], American: [], Russian: [] };
for (const c of Object.values(CARDS)) DECKS[c.nation].push(c.id);
for (const n of Object.keys(DECKS) as Nation[]) DECKS[n].sort((a, b) => CARDS[a].number - CARDS[b].number);

/** The 72 card ids of a nation's Fate deck, in card-number order (a fresh copy). */
export function deckOf(nation: Nation): CardId[] {
  return [...DECKS[nation]];
}

// ---------------------------------------------------------------------------------------------------------------------
// Counters

/** Every counter type by id "<Nation>/<name>", e.g. "German/Rifle Squad", "American/Lt Blankenship". */
export const COUNTERS: Readonly<Record<string, CounterType>> = Object.freeze(
  Object.fromEntries((countersJson.counters as CounterType[]).map((c) => [c.id, Object.freeze(c)])),
);

/** The counter type `name` of `nation`; throws if there is none. */
export function counterByName(nation: Nation, name: string): CounterType {
  const c = COUNTERS[`${nation}/${name}`];
  if (!c) throw new Error(`No counter "${name}" for ${nation}`);
  return c;
}

const QUALITY_NAME: Record<Quality, string> = { elite: 'Elite', line: 'Line', green: 'Green' };

/** The Team counter type id of a nation's troop quality (Light Wounds §A36 and Deploy §E52 use the OB quality). */
export function teamFor(nation: Nation, quality: Quality): string {
  return counterByName(nation, `${QUALITY_NAME[quality]} Team`).id;
}

// ---------------------------------------------------------------------------------------------------------------------
// Objective chits and smoke markers

export interface ObjectiveChit {
  id: ChitId;
  /** The Objective it values (1..5), 'all' for each of the five (S, T, U), or null (V, W, X). */
  objective: number | 'all' | null;
  vp: number;
  /** False for chits without a secret side (R, V, W, X): always placed open (§7.3.3). */
  secret: boolean;
  effect?: 'suddenDeathWin' | 'doubleExitVp' | 'doubleEliminationVp';
}

/** The 22 Objective chits A..X (no I, O), §7.3.2. */
export const OBJECTIVE_CHITS: Readonly<Record<ChitId, ObjectiveChit>> = Object.freeze(
  Object.fromEntries(
    Object.entries(countersJson.objectiveChits).map(([id, c]) => [id, Object.freeze({ id, ...(c as Omit<ObjectiveChit, 'id'>) })]),
  ),
);

/** The hindrance values of the 50 Smoke markers in the cup (1..5 six each, 6..10 four each). */
export const SMOKE_MIX: readonly number[] = Object.freeze(
  Object.entries(countersJson.smokeMix as Record<string, number>).flatMap(([v, n]) => Array<number>(n).fill(Number(v))),
);
